CREATE TABLE "member_access_scopes" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"org_id" text NOT NULL,
	"user_id" text NOT NULL,
	"company_id" uuid NOT NULL,
	"work_unit_id" uuid,
	"area" text NOT NULL,
	"granted_by" text NOT NULL,
	"granted_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "uq_member_access_scopes" UNIQUE NULLS NOT DISTINCT("org_id","user_id","company_id","work_unit_id","area"),
	CONSTRAINT "member_access_scopes_area_check" CHECK ("member_access_scopes"."area" in ('safety', 'health'))
);
